"""(T)NPSE: Neural Posterior Score Estimation with conditional score-based diffusion models.

Implements NPSE (amortised) and TSNPSE (truncated sequential) with VE and VP SDEs,
following Sharrock, Simons et al. (ICML 2024), Sections 2-3 and Appendix E.3.
"""
import math
import numpy as np
import torch
import torch.nn as nn


# ----------------------------------------------------------------------------- network
def mlp(i, o, h=256, n=3):
    layers, d = [], i
    for _ in range(n - 1):
        layers += [nn.Linear(d, h), nn.SiLU()]
        d = h
    layers += [nn.Linear(d, o)]
    return nn.Sequential(*layers)


def sinusoidal(t, dim=64):
    half = dim // 2
    i = torch.arange(half, dtype=t.dtype)
    freqs = 1.0 / (10000 ** (i / (half - 1)))
    a = t[:, None] * freqs[None]
    return torch.cat([torch.sin(a), torch.cos(a)], -1)


class ScoreNet(nn.Module):
    def __init__(self, d, p):
        super().__init__()
        de, pe = max(30, 4 * d), max(30, 4 * p)
        self.th_net = mlp(d, de)
        self.x_net = mlp(p, pe)
        self.net = mlp(de + pe + 64, d)

    def forward(self, th, x, t):
        h = torch.cat([self.th_net(th), self.x_net(x), sinusoidal(t)], -1)
        return self.net(h)


# ----------------------------------------------------------------------------- SDEs
class VESDE:
    def __init__(self, sigma_min, sigma_max):
        self.smin, self.smax = sigma_min, sigma_max
        self.eps = 1e-5

    def marginal(self, t):  # mean coef, std
        return torch.ones_like(t), self.smin * (self.smax / self.smin) ** t

    def f(self, x, t):
        return torch.zeros_like(x)

    def g2(self, t):
        s = self.smin * (self.smax / self.smin) ** t
        return s ** 2 * 2 * math.log(self.smax / self.smin)

    def prior_sample(self, n, d):
        return torch.randn(n, d) * self.smax

    def prior_logp(self, z):
        d = z.shape[-1]
        return -0.5 * (z ** 2).sum(-1) / self.smax ** 2 - d * math.log(self.smax) - 0.5 * d * math.log(2 * math.pi)

    def div_f(self, t, d):
        return 0.0


class VPSDE:
    def __init__(self, bmin=0.1, bmax=11.0):
        self.bmin, self.bmax = bmin, bmax
        self.eps = 1e-3

    def _int(self, t):
        return self.bmin * t + 0.5 * t ** 2 * (self.bmax - self.bmin)

    def beta(self, t):
        return self.bmin + t * (self.bmax - self.bmin)

    def marginal(self, t):
        I = self._int(t)
        return torch.exp(-0.5 * I), torch.sqrt(1 - torch.exp(-I))

    def f(self, x, t):
        return -0.5 * self.beta(t)[:, None] * x

    def g2(self, t):
        return self.beta(t)

    def prior_sample(self, n, d):
        return torch.randn(n, d)

    def prior_logp(self, z):
        d = z.shape[-1]
        return -0.5 * (z ** 2).sum(-1) - 0.5 * d * math.log(2 * math.pi)

    def div_f(self, t, d):
        return -0.5 * self.beta(t) * d


# ----------------------------------------------------------------------------- estimator
class NPSE:
    def __init__(self, d, p, sde_type="ve", sigma_min=0.05, seed=0):
        torch.manual_seed(seed)
        self.d, self.p = d, p
        self.sde_type, self.sigma_min = sde_type, sigma_min
        self.net = ScoreNet(d, p)
        self.opt = torch.optim.Adam(self.net.parameters(), lr=1e-4)
        self.sde = None

    def set_standardisation(self, th, x):
        """Uses (first-round) training data for standardisation and sigma_max."""
        self.th_mu, self.th_sd = th.mean(0), th.std(0).clamp_min(1e-8)
        self.x_mu, self.x_sd = x.mean(0), x.std(0).clamp_min(1e-8)
        if self.sde_type == "ve":
            z = (th - self.th_mu) / self.th_sd
            zs = z[torch.randperm(len(z))[:3000]]
            smax = torch.cdist(zs, zs).max().item()  # Technique 1 of Song & Ermon (2020)
            self.sde = VESDE(self.sigma_min, max(smax, 2 * self.sigma_min))
        else:
            self.sde = VPSDE()

    def zt(self, th):
        return (th - self.th_mu) / self.th_sd

    def zx(self, x):
        return (x - self.x_mu) / self.x_sd

    def loss(self, z0, xs, gen=None):
        n = len(z0)
        t = torch.rand(n, generator=gen) * (1 - self.sde.eps) + self.sde.eps
        m, s = self.sde.marginal(t)
        eps = torch.randn(z0.shape, generator=gen)
        zt = m[:, None] * z0 + s[:, None] * eps
        score = self.net(zt, xs, t)
        # lambda_t = sigma_t^2 weighting  ->  || sigma_t * s + eps ||^2
        return ((s[:, None] * score + eps) ** 2).sum(-1).mean()

    def train(self, th, x, max_iters=3000, batch_size=50, patience=1000, val_every=10):
        z, xs = self.zt(th), self.zx(x)
        n = len(z)
        perm = torch.randperm(n)
        nv = max(int(0.15 * n), 1)
        vi, ti = perm[:nv], perm[nv:]
        zv, xv, ztr, xtr = z[vi], xs[vi], z[ti], xs[ti]
        best, best_state, since = float("inf"), None, 0
        g = torch.Generator().manual_seed(123)
        for it in range(max_iters):
            idx = torch.randint(0, len(ztr), (min(batch_size, len(ztr)),))
            l = self.loss(ztr[idx], xtr[idx])
            self.opt.zero_grad()
            l.backward()
            self.opt.step()
            if it % val_every == 0:
                with torch.no_grad():
                    g.manual_seed(123)  # fixed noise for a low-variance validation loss
                    vl = self.loss(zv, xv, gen=g).item()
                if vl < best:
                    best, since = vl, 0
                    best_state = {k: v.clone() for k, v in self.net.state_dict().items()}
                else:
                    since += val_every
                    if since >= patience:
                        break
        self.net.load_state_dict(best_state)
        return it + 1

    # ---------------------------------------------------------------- probability flow ODE
    def _drift(self, z, xo, t):
        tt = torch.full((len(z),), t)
        return self.sde.f(z, tt) - 0.5 * self.sde.g2(tt)[:, None] * self.net(z, xo.expand(len(z), -1), tt)

    @torch.no_grad()
    def sample(self, x_obs, n, steps=200, chunk=10000):
        """Sample by integrating the probability-flow ODE backwards with fixed-step RK4."""
        xo = self.zx(x_obs.reshape(1, -1))
        out = []
        for c in range(0, n, chunk):
            m = min(chunk, n - c)
            z = self.sde.prior_sample(m, self.d)
            ts = np.linspace(1.0, self.sde.eps, steps + 1)
            for i in range(steps):
                t0, t1 = ts[i], ts[i + 1]
                h = t1 - t0
                k1 = self._drift(z, xo, t0)
                k2 = self._drift(z + 0.5 * h * k1, xo, t0 + 0.5 * h)
                k3 = self._drift(z + 0.5 * h * k2, xo, t0 + 0.5 * h)
                k4 = self._drift(z + h * k3, xo, t1)
                z = z + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)
            out.append(z)
        z = torch.cat(out)
        return z * self.th_sd + self.th_mu

    def _drift_div(self, z, xo, t):
        with torch.enable_grad():
            z = z.detach().requires_grad_(True)
            tt = torch.full((len(z),), t)
            s = self.net(z, xo.expand(len(z), -1), tt)
            div_s = torch.zeros(len(z))
            for j in range(self.d):  # exact trace of the Jacobian
                div_s = div_s + torch.autograd.grad(s[:, j].sum(), z, retain_graph=j < self.d - 1)[0][:, j]
        g2 = self.sde.g2(tt)
        drift = self.sde.f(z, tt) - 0.5 * g2[:, None] * s
        div = self.sde.div_f(tt, self.d) - 0.5 * g2 * div_s
        return drift.detach(), div.detach()

    def log_prob(self, th, x_obs, steps=50, chunk=5000):
        """log p(theta | x_obs) via the instantaneous change-of-variables formula (RK4, forward in time)."""
        xo = self.zx(x_obs.reshape(1, -1))
        res = []
        for c in range(0, len(th), chunk):
            z = self.zt(th[c:c + chunk])
            lp = torch.zeros(len(z))
            ts = np.linspace(self.sde.eps, 1.0, steps + 1)
            for i in range(steps):
                t0, t1 = ts[i], ts[i + 1]
                h = t1 - t0
                k1, d1 = self._drift_div(z, xo, t0)
                k2, d2 = self._drift_div(z + 0.5 * h * k1, xo, t0 + 0.5 * h)
                k3, d3 = self._drift_div(z + 0.5 * h * k2, xo, t0 + 0.5 * h)
                k4, d4 = self._drift_div(z + h * k3, xo, t1)
                z = z + h / 6 * (k1 + 2 * k2 + 2 * k3 + k4)
                lp = lp + h / 6 * (d1 + 2 * d2 + 2 * d3 + d4)
            res.append(self.sde.prior_logp(z) + lp - torch.log(self.th_sd).sum())
        return torch.cat(res)


# ----------------------------------------------------------------------------- helpers
def in_support(prior, th):
    lp = prior.log_prob(th)
    return torch.isfinite(lp)


def sample_posterior(model, prior, x_obs, n):
    """Samples from the learnt posterior, discarding samples outside the prior support."""
    out, got = [], 0
    for _ in range(10):
        s = model.sample(x_obs, int((n - got) * 1.2) + 100)
        s = s[in_support(prior, s)]
        out.append(s)
        got += len(s)
        if got >= n:
            break
    return torch.cat(out)[:n]


def truncated_prior_sampler(model, prior, x_obs, n_hpr=5000, eps=5e-4, max_tries=200):
    """Returns a sampler for the prior truncated to the HPR_eps of the current posterior (App. E.3.3)."""
    post = sample_posterior(model, prior, x_obs, n_hpr)
    lp = model.log_prob(post, x_obs)
    kappa = torch.quantile(lp, eps)
    lo, hi = post.min(0).values, post.max(0).values

    def sampler(m):
        acc, got = [], 0
        for _ in range(max_tries):
            cand = prior.sample((max(20 * m, 20000),))
            cand = cand[((cand >= lo) & (cand <= hi)).all(-1)]  # cheap hypercube pre-rejection
            if len(cand) > 0:
                cand = cand[: 4 * (m - got) + 200]
                lpc = model.log_prob(cand, x_obs)
                ok = cand[lpc > kappa]
                acc.append(ok)
                got += len(ok)
            if got >= m:
                break
        res = torch.cat(acc) if acc else torch.zeros(0, post.shape[1])
        if len(res) < m:  # fall back to filling with approximate posterior samples
            res = torch.cat([res, sample_posterior(model, prior, x_obs, m - len(res))])
        return res[:m]

    return sampler


def run_npse(task, budget, sde_type, sigma_min, seed=0):
    prior, sim = task.get_prior_dist(), task.get_simulator()
    torch.manual_seed(seed)
    th = prior.sample((budget,))
    x = sim(th)
    model = NPSE(th.shape[1], x.shape[1], sde_type, sigma_min, seed)
    model.set_standardisation(th, x)
    bs = 500 if budget >= 100000 else 50
    model.train(th, x, batch_size=bs)
    return model


def run_tsnpse(task, budget, sde_type, sigma_min, x_obs, rounds=10, seed=0, log=print):
    prior, sim = task.get_prior_dist(), task.get_simulator()
    torch.manual_seed(seed)
    M = budget // rounds
    bs = 500 if budget >= 100000 else 200
    th_all, x_all = [], []
    proposal = lambda m: prior.sample((m,))
    model = None
    for r in range(rounds):
        th = proposal(M)
        x = sim(th)
        th_all.append(th)
        x_all.append(x)
        TH, X = torch.cat(th_all), torch.cat(x_all)
        if model is None:
            model = NPSE(th.shape[1], x.shape[1], sde_type, sigma_min, seed)
            model.set_standardisation(TH, X)  # first round data only (addendum)
        it = model.train(TH, X, batch_size=bs)
        log(f"  round {r+1}/{rounds}: n={len(TH)} iters={it}")
        if r < rounds - 1:
            proposal = truncated_prior_sampler(model, prior, x_obs)
    return model

